begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af880000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','keys-owner@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf880000-0000-4000-8000-000000000001','Recebedor fictício','keys-synthetic','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cf880000-0000-4000-8000-000000000001','bf880000-0000-4000-8000-000000000001','Sede Recebedor','sede','headquarters'),('cf880000-0000-4000-8000-000000000002','bf880000-0000-4000-8000-000000000001','Campus Recebedor','campus','campus');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf880000-0000-4000-8000-000000000001','af880000-0000-4000-8000-000000000001','owner','active','cf880000-0000-4000-8000-000000000001');
select set_config('keys.org','bf880000-0000-4000-8000-000000000001',true);select set_config('keys.unit','cf880000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"af880000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.finance_f1(current_setting('keys.org')::uuid,array[current_setting('keys.unit')::uuid],'catalog','{"id":"df880000-0000-4000-8000-000000000001","kind":"account","name":"Banco Recebedor"}');
select public.finance_f1(current_setting('keys.org')::uuid,array[current_setting('keys.unit')::uuid],'catalog','{"id":"df880000-0000-4000-8000-000000000002","kind":"category","name":"Doações Recebedor","direction":"income"}');
select public.finance_f1(current_setting('keys.org')::uuid,array[current_setting('keys.unit')::uuid],'entry',jsonb_build_object('id','ab880000-0000-4000-8000-000000000001','kind','income','amountCents','1000','description','Previsão inicial fictícia','account','df880000-0000-4000-8000-000000000001','category','df880000-0000-4000-8000-000000000002','competence',current_date,'due',current_date,'method','pix'));
reset role;

set local role authenticated;
select public.finance_f1(current_setting('keys.org')::uuid,array[current_setting('keys.unit')::uuid],'entry',jsonb_build_object('id','ab880000-0000-4000-8000-000000000002','kind','income','amountCents','10000','description','Receita fictícia F6','account','df880000-0000-4000-8000-000000000001','category','df880000-0000-4000-8000-000000000002','party','Pessoa fictícia F6','competence',current_date,'due',current_date,'paid',current_date,'method','pix'));
select set_config('keys.filters',jsonb_build_object('from',current_date,'to',current_date,'dateBy','cash','report','book')::text,true);


reset role;
select ok(not has_function_privilege('anon','public.finance_receiver_key_check(uuid,uuid,uuid,text,jsonb)','execute'),'visitante não acessa validação técnica');
select ok(not has_function_privilege('authenticated','public.finance_receiver_key_check(uuid,uuid,uuid,text,jsonb)','execute'),'cliente não forja prova técnica');
select set_config('keys.proof',jsonb_build_object('provider','mercado_pago','environment','production','version',0,'externalId','123','holder','Titular fictício','sealed',repeat('x',100),'expiresAt',now()+interval '24 hours','webhookConfigured',false)::text,true);
select lives_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'complete',current_setting('keys.proof')::jsonb)$$,'prova técnica cria conta sem ativar cobranças');
select set_config('keys.receiver',(select id::text from private.finance_receivers where organization_id=current_setting('keys.org')::uuid),true);
select set_config('keys.account',(select account_id::text from private.finance_receivers where id=current_setting('keys.receiver')::uuid),true);
select ok(not (select payments_enabled from private.finance_receivers where id=current_setting('keys.receiver')::uuid),'validar não habilita dinheiro real');
select is((select count(*)::integer from private.finance_provider_accounts where receiver_id=current_setting('keys.receiver')::uuid),1,'conta de controle criada uma única vez');
select throws_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000099',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'inspect','{"provider":"mercado_pago","environment":"production","version":2}')$$,'42501',null,'identidade externa à igreja não lê segredo');
select throws_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'complete',current_setting('keys.proof')::jsonb)$$,'40001',null,'prova concorrente obsoleta não substitui chave');
set local role authenticated;
select lives_ok($$select public.finance_receiver_settings(current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'configure',jsonb_build_object('provider','mercado_pago','environment','production','version',2,'account',current_setting('keys.account'),'units',jsonb_build_array(current_setting('keys.unit')),'methods',jsonb_build_array('pix'),'holderConfirmed',true))$$,'titular define conta e igreja explicitamente');
reset role;
select throws_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'activate','{"provider":"mercado_pago","environment":"production","version":3,"confirmed":true}')$$,'22023',null,'falta de assinatura impede habilitação');
select lives_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'complete',current_setting('keys.proof')::jsonb||'{"version":3,"webhookConfigured":true}')$$,'nova validação instala assinatura e desabilita configuração anterior');
select ok(not (select holder_confirmed or payments_enabled from private.finance_receivers where id=current_setting('keys.receiver')::uuid),'troca da chave exige nova confirmação');
set local role authenticated;
select public.finance_receiver_settings(current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'configure',jsonb_build_object('provider','mercado_pago','environment','production','version',4,'account',current_setting('keys.account'),'units',jsonb_build_array(current_setting('keys.unit')),'methods',jsonb_build_array('pix'),'holderConfirmed',true));
reset role;
select throws_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'activate','{"provider":"mercado_pago","environment":"production","version":5,"confirmed":false}')$$,'22023',null,'confirmação é obrigatória');
select lives_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'activate','{"provider":"mercado_pago","environment":"production","version":5,"confirmed":true}')$$,'responsável habilita somente conexão pronta');
select ok((select payments_enabled from private.finance_receivers where id=current_setting('keys.receiver')::uuid),'ativação explícita registrada');
select is((public.finance_digital_connection(current_setting('keys.receiver')::uuid)->>'paymentsEnabled')::boolean,true,'checkout recebe ativação confiável do banco');
select lives_ok($$select public.finance_receiver_key_check('af880000-0000-4000-8000-000000000001',current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'renew',current_setting('keys.proof')::jsonb||'{"version":6,"webhookConfigured":true}')$$,'revalidar mesmo titular preserva configuração confirmada');
select ok((select payments_enabled and holder_confirmed from private.finance_receivers where id=current_setting('keys.receiver')::uuid),'renovação não desabilita a conta confirmada');
set local role authenticated;
select public.finance_receiver_settings(current_setting('keys.org')::uuid,current_setting('keys.unit')::uuid,'configure',jsonb_build_object('provider','mercado_pago','environment','production','version',7,'account',current_setting('keys.account'),'units',jsonb_build_array(current_setting('keys.unit')),'methods',jsonb_build_array('card'),'holderConfirmed',true));
reset role;
select ok(not (select payments_enabled from private.finance_receivers where id=current_setting('keys.receiver')::uuid),'alterar métodos exige nova habilitação');
select is((select count(*)::integer from private.finance_entries where organization_id=current_setting('keys.org')::uuid),2,'configuração não cria lançamentos ou pagamentos');
select ok(not exists(select 1 from private.finance_receiver_events where receiver_id=current_setting('keys.receiver')::uuid and details::text like '%'||repeat('x',30)||'%'),'eventos não copiam credenciais');
select * from finish();
rollback;
